app.get('/orders', async (req, res, next) => {
  try {
    const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);

    let createdAt = null;
    let id = null;
    if (req.query.cursor) {
      try {
        [createdAt, id] = JSON.parse(Buffer.from(req.query.cursor, 'base64url').toString());
      } catch {
        return res.status(400).json({ error: 'Invalid cursor.' });
      }
    }

    // Fetch one extra row to know whether another page exists.
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_created_at
         FROM orders
        WHERE $1::timestamptz IS NULL
           OR (created_at, id) < ($1::timestamptz, $2::bigint)
        ORDER BY created_at DESC, id DESC
        LIMIT $3`,
      [createdAt, id, limit + 1]
    );

    const last = rows.length > limit ? rows[limit - 1] : null;
    const nextCursor = last
      ? Buffer.from(JSON.stringify([last.cursor_created_at, last.id])).toString('base64url')
      : null;

    res.json({
      orders: rows.slice(0, limit).map(({ cursor_created_at, ...order }) => order),
      nextCursor,
    });
  } catch (err) {
    next(err);
  }
});
```

This assumes `pool` is your `pg` Pool and `id` is a bigint (change the `::bigint` cast if it is a UUID), and it needs `CREATE INDEX ON orders (created_at DESC, id DESC);` to stay fast.

The cursor carries `created_at` as text because a JavaScript `Date` drops PostgreSQL's microseconds, which would skip or repeat rows.

