```go
package main

import (
	"flag"
	"fmt"
	"os"
)

func main() {
	verbose := flag.Bool("verbose", false, "print extra output")
	output := flag.String("output", "out.txt", "file to write results to")

	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), "Usage: %s [flags] <input>...\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.Parse()

	inputs := flag.Args() // positional arguments
	if len(inputs) == 0 {
		flag.Usage()
		os.Exit(2)
	}

	fmt.Println(*verbose, *output, inputs)
}
```

Swap in your own flag definitions. `-h` and `-help` print the generated help. Parsing stops at the first positional argument, so flags must come before them.

```ts
type Job<T> = () => Promise<T>;

export class JobQueue {
  private running = 0;
  private pending: Array<() => Promise<void>> = [];
  private emptyWaiters: Array<() => void> = [];

  constructor(private concurrency: number, private retries = 3) {}

  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => this.run(job).then(resolve, reject));
      this.next();
    });
  }

  onEmpty(): Promise<void> {
    if (this.running === 0 && this.pending.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.emptyWaiters.push(resolve));
  }

  private async run<T>(job: Job<T>): Promise<T> {
    for (let attempt = 0; ; attempt++) {
      try {
        return await job();
      } catch (err) {
        if (attempt >= this.retries) throw err;
      }
    }
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      const start = this.pending.shift()!;
      this.running++;
      start().finally(() => {
        this.running--;
        this.next();
      });
    }
    if (this.running === 0 && this.pending.length === 0) {
      for (const resolve of this.emptyWaiters.splice(0)) resolve();
    }
  }
}
```

Use it as `const queue = new JobQueue(4); queue.add(() => doWork()); await queue.onEmpty();`. The promise returned by `add` rejects once a job has failed its first run and all three retries, so catch it to avoid an unhandled rejection.

Retries run immediately with no delay, and `onEmpty` resolves whether or not any jobs failed.
